class Solution {
    int heights[100005];
    int depths[100005];
    std::vector<std::pair<int, int>> top2[100005];

    int getHeight(TreeNode* node, int d) {
        if (!node) return -1;
        depths[node->val] = d;
        int h = 1 + std::max(getHeight(node->left, d + 1), getHeight(node->right, d + 1));
        heights[node->val] = h;
        auto& v = top2[d];
        v.push_back({h, node->val});
        std::sort(v.rbegin(), v.rend());
        if (v.size() > 2) v.pop_back();
        return h;
    }
public:
    std::vector<int> treeQueries(TreeNode* root, std::vector<int>& queries) {
        getHeight(root, 0);
        std::vector<int> ans;
        for (int q : queries) {
            int d = depths[q];
            const auto& cand = top2[d];
            if (cand.size() == 1) {
                ans.push_back(d - 1);
            } else if (cand[0].second == q) {
                ans.push_back(d + cand[1].first);
            } else {
                ans.push_back(d + cand[0].first);
            }
        }
        return ans;
    }
};

class Solution {
    int[] heights = new int[100005];
    int[] depths = new int[100005];
    int[][] top1 = new int[100005][2];
    int[][] top2 = new int[100005][2];

    int getHeight(TreeNode node, int d) {
        if (node == null) return -1;
        depths[node.val] = d;
        int h = 1 + Math.max(getHeight(node.left, d + 1), getHeight(node.right, d + 1));
        heights[node.val] = h;
        if (h > top1[d][0]) {
            top2[d][0] = top1[d][0];
            top2[d][1] = top1[d][1];
            top1[d][0] = h;
            top1[d][1] = node.val;
        } else if (h > top2[d][0]) {
            top2[d][0] = h;
            top2[d][1] = node.val;
        }
        return h;
    }

    public int[] treeQueries(TreeNode root, int[] queries) {
        for (int i = 0; i < 100005; i++) {
            top1[i][0] = -1;
            top2[i][0] = -1;
        }
        getHeight(root, 0);
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            int d = depths[q];
            if (top1[d][1] == q) {
                ans[i] = top2[d][0] == -1 ? d - 1 : d + top2[d][0];
            } else {
                ans[i] = d + top1[d][0];
            }
        }
        return ans;
    }
}

var treeQueries = function(root, queries) {
    const heights = new Map();
    const depths = new Map();
    const depthToNodes = new Map();

    const getHeight = (node, d) => {
        if (!node) return -1;
        depths.set(node.val, d);
        const h = 1 + Math.max(getHeight(node.left, d + 1), getHeight(node.right, d + 1));
        heights.set(node.val, h);
        if (!depthToNodes.has(d)) depthToNodes.set(d, []);
        depthToNodes.get(d).push({ h, val: node.val });
        return h;
    };
    getHeight(root, 0);

    const top2 = new Map();
    for (const [d, nodes] of depthToNodes.entries()) {
        nodes.sort((a, b) => b.h - a.h);
        top2.set(d, nodes.slice(0, 2));
    }

    const ans = [];
    for (const q of queries) {
        const d = depths.get(q);
        const cand = top2.get(d);
        if (cand.length === 1) {
            ans.push(d - 1);
        } else if (cand[0].val === q) {
            ans.push(d + cand[1].h);
        } else {
            ans.push(d + cand[0].h);
        }
    }
    return ans;
};
